const sample = {
  "demo": true,
  "employee": "Leo",
  "merchant": "City Bistro",
  "category": "meal",
  "amount": 96,
  "currency": "USD",
  "receipt": true
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const category = String(item.category || 'other').toLowerCase();
const amount = Number(item.amount || 0);
const caps = { meal: 75, rideshare: 120, lodging: 350, software: 200, other: 150 };
const cap = caps[category] ?? caps.other;
const receipt = Boolean(item.receipt || item.filename);
let route = 'approve';
const reasons = [];
if (amount > cap) { route = 'exception'; reasons.push('over the ' + cap + ' ' + category + ' cap'); }
if (!receipt && amount >= 25) { route = 'needs-receipt'; reasons.push('missing receipt'); }
if (item.merchant && /casino|gift card/i.test(item.merchant)) { route = 'reject'; reasons.push('merchant is out of policy'); }
const record = {
  employee: item.employee || item.email || '',
  merchant: item.merchant || '',
  category, amount, currency: item.currency || 'USD', cap, receipt, route,
  reasons: reasons.join('; ') || 'within policy',
  title: (item.merchant || category) + ' ' + amount,
};
return {
  summary: record.title + ' is ' + route + '. ' + record.reasons + '.',
  route,
  record,
  slackText: route.toUpperCase() + ' expense ' + record.title,
  actions: [{ app: 'Sheets', operation: 'append', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'expense-policy-flagger',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
